// Prepare payload for TradingAgents multi-agent system
// TradingAgents expects: ticker symbol + date
const agentOutput = $input.first().json.output || $input.first().json;
const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD

// Extract HIGH conviction pairs from agent output
// The agent returns text - parse it for high confidence pairs
const outputText = typeof agentOutput === 'string' ? agentOutput : JSON.stringify(agentOutput);

// Build payload array for TradingAgents
// TradingAgents.propagate(ticker, date) - crypto tickers need to be adapted
// For crypto, use the base symbol (BTC, ETH, SOL etc)
const cryptoSymbols = [];
const pairRegex = /\b([A-Z]{2,10})USDT\b/g;
let match;
while ((match = pairRegex.exec(outputText)) !== null) {
  const baseSymbol = match[1];
  if (!cryptoSymbols.includes(baseSymbol) && 
      !['USDC', 'USDT', 'BUSD', 'DAI', 'WBTC'].includes(baseSymbol)) {
    cryptoSymbols.push(baseSymbol);
  }
}

return cryptoSymbols.slice(0, 5).map(symbol => ({
  json: {
    ticker: symbol,
    date: today,
    binancePair: `${symbol}USDT`,
    source: 'hype_scanner',
    tradingAgentsEndpoint: 'http://tradingagents-api:8001/analyze'
  }
}));

const items = $input.all();
const cryptoData = items[0].json.data;

const MIN_PERCENT_CHANGE = 5;   // lowered from 40 so we get more candidates  
const MIN_MARKET_CAP = 5000000;  // $5M
const MIN_VOLUME = 500000;       // $500k

// Binance spot market suffix list - only include coins tradeable on Binance spot
const BINANCE_QUOTE_CURRENCIES = ['USDT', 'USDC', 'BTC', 'ETH', 'BNB'];

const filteredTokens = [];

for (const token of cryptoData) {
  const q = token.quote?.USD;
  if (!q) continue;

  const percentChange = q.percent_change_24h || 0;
  const marketCap = q.market_cap || 0;
  const volume = q.volume_24h || 0;
  const price = q.price || 0;

  if (percentChange >= MIN_PERCENT_CHANGE && 
      marketCap >= MIN_MARKET_CAP && 
      volume >= MIN_VOLUME &&
      price > 0) {

    // Build primary Binance spot pair (always USDT first)
    const symbol = token.symbol.toUpperCase();
    const binancePair = `${symbol}USDT`;

    filteredTokens.push({
      json: {
        name: token.name,
        symbol: symbol,
        binancePair: binancePair,          // e.g. "BTCUSDT"
        price: price,
        percent_change_1h: q.percent_change_1h || 0,
        percent_change_24h: percentChange,
        percent_change_7d: q.percent_change_7d || 0,
        market_cap: marketCap,
        market_cap_rank: token.cmc_rank || 0,
        volume_24h: volume,
        volume_change_24h: q.volume_change_24h || 0,
        tags: token.tags || [],
        source: 'CMC'
      }
    });
  }
}

return filteredTokens;

const items = $input.all();

const sectorMapping = {
  'ai': ['ai', 'artificial-intelligence', 'ai-big-data', 'gpt', 'machine-learning', 'large-language-model'],
  'depin': ['depin', 'infrastructure', 'storage', 'oracle', 'iot', 'wireless'],
  'defi': ['defi', 'dex', 'lending', 'yield-farming', 'derivatives', 'stablecoin', 'amm', 'liquid-staking'],
  'gaming': ['gaming', 'metaverse', 'nft', 'play-to-earn', 'collectibles', 'gamefi'],
  'rwa': ['rwa', 'real-world-assets', 'tokenized-assets', 'real-estate'],
  'layer1': ['layer-1', 'platform', 'smart-contracts', 'pos', 'pow'],
  'layer2': ['layer-2', 'scaling', 'rollup', 'zk', 'optimistic'],
  'meme': ['meme', 'memes', 'dog-themed', 'cat-themed', 'animal'],
  'infrastructure': ['oracle', 'data', 'privacy', 'interoperability', 'bridge', 'cross-chain'],
  'social': ['social', 'dao', 'governance', 'identity'],
  'payments': ['payments', 'remittance', 'currency', 'stablecoin']
};

function determineSector(tags) {
  if (!tags || tags.length === 0) return 'other';
  for (const [sector, keywords] of Object.entries(sectorMapping)) {
    for (const tag of tags) {
      const t = (typeof tag === 'string' ? tag : tag.slug || '').toLowerCase();
      for (const kw of keywords) {
        if (t.includes(kw)) return sector;
      }
    }
  }
  return 'other';
}

// Assign sectors
const tokensWithSectors = items.map(item => ({
  ...item.json,
  sector: determineSector(item.json.tags)
}));

// Group by sector
const sectorGroups = {};
for (const tkn of tokensWithSectors) {
  if (!sectorGroups[tkn.sector]) sectorGroups[tkn.sector] = [];
  sectorGroups[tkn.sector].push(tkn);
}

// Build sector stats
const sectorStats = Object.entries(sectorGroups).map(([sector, tokens]) => {
  const avgGain = (tokens.reduce((s, t) => s + t.percent_change_24h, 0) / tokens.length).toFixed(2);
  const totalVolume = tokens.reduce((s, t) => s + t.volume_24h, 0);
  return {
    sector,
    count: tokens.length,
    avgGain: parseFloat(avgGain),
    totalVolume,
    tokens: tokens.sort((a, b) => b.percent_change_24h - a.percent_change_24h)
  };
}).sort((a, b) => b.avgGain - a.avgGain);

// Return single item with all data for the Main Agent
return [{
  json: {
    sectorStats,
    allTokens: tokensWithSectors,
    totalTokensFound: tokensWithSectors.length,
    source: items[0]?.json?.source || 'CMC',
    timestamp: new Date().toISOString()
  }
}];

const items = $input.all();
const cryptoData = items[0]?.json?.coins ?? [];

if (!Array.isArray(cryptoData)) {
  throw new Error(`Expected items[0].json.coins to be an array, got ${typeof cryptoData}`);
}

return cryptoData.map(entry => {
