const items = $input.all();

// Collect all tokens from both sources
let allTokens = [];
let allSectorStats = [];

for (const item of items) {
  const data = item.json;
  if (data.allTokens) allTokens.push(...data.allTokens);
  if (data.sectorStats) allSectorStats.push(...data.sectorStats);
}

// Deduplicate by symbol (prefer CMC data if duplicate)
const seen = new Set();
const dedupedTokens = [];
for (const token of allTokens) {
  if (!seen.has(token.symbol)) {
    seen.add(token.symbol);
    dedupedTokens.push(token);
  }
}

// Sort by percent_change_24h descending
dedupedTokens.sort((a, b) => b.percent_change_24h - a.percent_change_24h);

// Build the prompt context for the Main Agent
const top20 = dedupedTokens.slice(0, 20);
const binancePairs = [...new Set(dedupedTokens.map(t => t.binancePair).filter(Boolean))];

let marketSummary = `=== CRYPTO HYPE & TREND SCANNER REPORT ===\n`;
marketSummary += `Generated: ${new Date().toISOString()}\n`;
marketSummary += `Total tokens found: ${dedupedTokens.length}\n\n`;

marketSummary += `--- TOP 20 MOVERS ---\n`;
for (const t of top20) {
  marketSummary += `${t.symbol} (${t.name}): +${t.percent_change_24h.toFixed(2)}% | MC: $${(t.market_cap/1e6).toFixed(1)}M | Vol: $${(t.volume_24h/1e6).toFixed(1)}M | Pair: ${t.binancePair} | Source: ${t.source}\n`;
}

// Sector momentum
marketSummary += `\n--- SECTOR MOMENTUM ---\n`;
const sectorMap = {};
for (const t of dedupedTokens) {
  const s = t.sector || 'trending';
  if (!sectorMap[s]) sectorMap[s] = [];
  sectorMap[s].push(t.percent_change_24h);
}
for (const [sector, gains] of Object.entries(sectorMap)) {
  const avg = (gains.reduce((a, b) => a + b, 0) / gains.length).toFixed(1);
  marketSummary += `${sector.toUpperCase()}: ${gains.length} tokens, avg +${avg}%\n`;
}

marketSummary += `\n--- ALL BINANCE PAIRS TO ANALYZE ---\n`;
marketSummary += binancePairs.join(', ') + '\n';

return [{
  json: {
    message: marketSummary,
    binancePairs,
    allTokens: dedupedTokens,
    totalTokens: dedupedTokens.length,
    timestamp: new Date().toISOString()
  }
}];
